@Test
public void testSignatureCreationWithExternalFilesystemXMLReference() throws Exception {
    // Set up the Configuration
    XMLSecurityProperties properties = new XMLSecurityProperties();
    XMLSecurityConstants.Action[] actions = new XMLSecurityConstants.Action[] { XMLSecurityConstants.SIGNATURE };
    properties.setOutAction(actions);
    // Set the key up
    KeyStore keyStore = KeyStore.getInstance("jks");
    keyStore.load(this.getClass().getClassLoader().getResource("transmitter.jks").openStream(), "default".toCharArray());
    Key key = keyStore.getKey("transmitter", "default".toCharArray());
    properties.setSignatureKey(key);
    X509Certificate cert = (X509Certificate) keyStore.getCertificate("transmitter");
    properties.setSignatureCerts(new X509Certificate[] { cert });
    SecurePart securePart = new SecurePart(new QName("urn:example:po", "PaymentInfo"), SecurePart.Modifier.Element);
    properties.addSignaturePart(securePart);
    securePart = new SecurePart("file://" + BASEDIR + "/src/test/resources/ie/baltimore/merlin-examples/merlin-xmlenc-five/plaintext.xml", new String[] { "http://www.w3.org/TR/2001/REC-xml-c14n-20010315" }, XMLSecurityConstants.NS_XMLDSIG_SHA1);
    properties.addSignaturePart(securePart);
    OutboundXMLSec outboundXMLSec = XMLSec.getOutboundXMLSec(properties);
    ByteArrayOutputStream baos = new ByteArrayOutputStream();
    XMLStreamWriter xmlStreamWriter = outboundXMLSec.processOutMessage(baos, "UTF-8");
    InputStream sourceDocument = this.getClass().getClassLoader().getResourceAsStream("ie/baltimore/merlin-examples/merlin-xmlenc-five/plaintext.xml");
    XMLStreamReader xmlStreamReader = xmlInputFactory.createXMLStreamReader(sourceDocument);
    XmlReaderToWriter.writeAll(xmlStreamReader, xmlStreamWriter);
    xmlStreamWriter.close();
    Document document = XMLUtils.createDocumentBuilder(false).parse(new ByteArrayInputStream(baos.toByteArray()));
    // Verify using DOM
    verifyUsingDOM(document, cert, properties.getSignatureSecureParts());
}

